{
  "questions": [
    {
      "n": 1,
      "start": "Wie schätzt der Stadtrat die aktuelle Situation",
      "end": "in Bezug auf die Sicherheit und Gesundheit der Sexarbeitenden"
    },
    {
      "n": 2,
      "start": "Welche konkreten Massnahmen bestehen derzeit oder",
      "end": "um Sexarbeitende in der Beschaffungsprostitution zu schützen"
    },
    {
      "n": 3,
      "start": "Wie werden Fachstellen aus den Bereichen Gesundheit, Sucht",
      "end": "in die Betreuung und Unterstützung der betroffenen Personen eingebunden?"
    },
    {
      "n": 4,
      "start": "Wie geht die Stadt mit den in Onlineforen dokumentierten, teils",
      "end": "um betroffene Personen vor digitaler Diffamierung oder Gefährdung zu schützen?"
    },
    {
      "n": 5,
      "start": "Wie werden die Anwohnenden im Gebiet Kreuzstutz über die Situation",
      "end": "um gegenseitiges Verständnis zu fördern?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Der Stadtrat stellt fest, dass sich die Situation im Gebiet Kreuzstutz",
      "end": "in den letzten Jahren deutlich beruhigt hat."
    },
    {
      "n": 2,
      "start": "Bei der Betrachtung von Massnahmen ist es wichtig, die folgende Differenzierung vorzunehmen: Die",
      "end": "betroffenen Personen sind primär nicht als Sexarbeitende zu betrachten, sondern als suchtbetroffene und sozial vulnerable Personen"
    },
    {
      "n": 3,
      "start": "Da die Beschaffungsprostitution im Gebiet Kreuzstutz derzeit nur vereinzelt festgestellt wird und kaum Meldungen eingehen,",
      "end": "bestehen in der Stadt Luzern keine spezialisierten Fachstellen, die ausschliesslich in diesem Bereich tätig sind."
    },
    {
      "n": 4,
      "start": "Der Stadtrat hält fest, dass auch im Internet klare rechtliche Grenzen gelten.",
      "end": "Betroffene Personen könnten bei Bedarf über ihre Rechte informiert und an geeignete Unterstützungsangebote triagiert werden."
    },
    {
      "n": 5,
      "start": "Zurzeit bestehen im Gebiet Kreuzstutz keine wahrnehmbaren Spannungen zwischen Anwohnenden und",
      "end": "den von Beschaffungsprostitution betroffenen Personen."
    }
  ],
  "submitter": "Zoé Stehlin und Christoph Landolt",
  "co_signatories": ["SP/JUSO-Fraktion"],
  "recommendation": "none",
  "reasoning": null
}
